sealed trait Node { def size: Long }
final case class File(bytes: Long) extends Node { def size: Long = bytes }
final case class Dir(children: List[Node]) extends Node { def size: Long = children.map(_.size).sum }

def report(node: Node): String = node match {          // exhaustive: no default needed
  case File(bytes)      => s"file($bytes)"
  case Dir(children)    => children.map(report).mkString("dir(", ",", ")")
}

