abstract class Component { def size: Long }

final class File(val bytes: Long) extends Component { def size: Long = bytes }

final class Dir extends Component {
  private val children = scala.collection.mutable.ArrayBuffer.empty[Component]
  def add(child: Component): Unit = children += child
  def size: Long = children.map(_.size).sum
}
